'use strict';
/**
 * test/status-generator.test.js
 *
 * STATUS.md is generated from brokers.js plus data/broker-health.json. STATUS.md
 * used to claim it was generated by a script that did not exist, and its table
 * drifted by hand. These tests pin the generator, and pin the committed file to
 * the generator's output so it cannot drift from its sources again.
 */

const { test, describe } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const brokers = require('../brokers');
const { renderStatus } = require('../scripts/generate-status');
const { explicitBrokers } = require('../lib/broker-health');

const ROOT = path.join(__dirname, '..');
const list = [
  { name: 'Alpha', method: 'direct-form', captchaLikely: false, usOnly: true, optOutUrl: 'https://a.example' },
  { name: 'Beta', method: 'search-form', captchaLikely: true, usOnly: false, optOutUrl: 'https://b.example', searchUrl: 'https://b.example/s' },
  { name: 'Gamma', method: 'manual', optOutUrl: 'https://g.example' },
  { name: 'Delta (email)', method: 'email', emailTo: 'x@example.com' },
  { name: 'Epsilon', method: 'direct-form', captchaLikely: false, optOutUrl: 'https://e.example', searchUrl: 'https://e.example/s', searchCheckedAt: '2026-11-10T00:00:00Z' },
];
const health = {
  checkedAt: '2026-11-17T06:23:00.000Z',
  runner: 'ci',
  summary: {},
  results: {
    Alpha: { status: 'ok', detail: 'fine', checkedAt: '2026-11-17T06:20:00.000Z', previousStatus: 'ok' },
    Beta: { status: 'blocked', detail: 'bot wall', checkedAt: '2026-11-17T06:21:00.000Z', previousStatus: null },
    Gamma: { status: 'drifted', detail: 'x', checkedAt: '2026-11-16T23:59:59.000Z', previousStatus: 'ok' },
    'Delta (email)': { status: 'n/a', detail: 'email', checkedAt: '2026-11-17T06:22:00.000Z', previousStatus: null },
    'Removed From Code': { status: 'ok', detail: 'stale', checkedAt: '2026-11-01T00:00:00.000Z', previousStatus: 'ok' },
  },
};

const brokerTable = (text) => text.split('## Explicit brokers')[1].split('\n## ')[0];
const rows = (text) => brokerTable(text).split('\n').filter((l) => /^\| /.test(l) && !/^\| (Broker|---)/.test(l));
const cells = (row) => row.split('|').slice(1, -1).map((c) => c.trim());

describe('renderStatus', () => {
  const text = renderStatus({ brokers: list, health });

  test('the table has the documented columns', () => {
    const head = text.split('\n').find((l) => l.startsWith('| Broker'));
    assert.deepEqual(cells(head), ['Broker', 'Method', 'CAPTCHA', 'Health', 'Checked', 'US-only', 'Search step']);
  });

  test('a checked broker shows its label and the date', () => {
    const alpha = cells(rows(text).find((r) => r.startsWith('| Alpha ')));
    assert.deepEqual(alpha.slice(0, 6), ['Alpha', 'direct-form', 'no', 'ok', '2026-11-17', 'yes']);
  });

  test('a broker with no result says "not checked yet"', () => {
    const out = renderStatus({ brokers: list, health: { results: {} } });
    const alpha = cells(rows(out).find((r) => r.startsWith('| Alpha ')));
    assert.equal(alpha[3], 'not checked yet');
    assert.equal(alpha[4], '-');
  });

  test('a missing or unreadable health file is the same as an empty one', () => {
    assert.equal(renderStatus({ brokers: list, health: null }), renderStatus({ brokers: list, health: { results: {} } }));
  });

  test('the date is the UTC day of the check', () => {
    const gamma = cells(rows(text).find((r) => r.startsWith('| Gamma ')));
    assert.equal(gamma[4], '2026-11-16');
  });

  test('CAPTCHA is n/a for manual and email brokers', () => {
    assert.equal(cells(rows(text).find((r) => r.startsWith('| Gamma ')))[2], 'n/a');
    assert.equal(cells(rows(text).find((r) => r.startsWith('| Delta')))[2], 'n/a');
    assert.equal(cells(rows(text).find((r) => r.startsWith('| Beta ')))[2], 'yes');
  });

  test('search step: yes with its date, yes when never checked, no without one', () => {
    const step = (name) => cells(rows(text).find((r) => r.startsWith(`| ${name} `)))[6];
    assert.equal(step('Epsilon'), 'yes (2026-11-10)');
    assert.equal(step('Beta'), 'yes (not checked)');
    assert.equal(step('Alpha'), 'no');
  });

  test('a broker in the health file but not in brokers.js is left out; one in brokers.js but not the file is kept', () => {
    assert.doesNotMatch(text, /Removed From Code/);
    assert.equal(rows(text).length, list.length);
  });

  test('the same input always renders the same text', () => {
    assert.equal(renderStatus({ brokers: list, health }), renderStatus({ brokers: [...list], health: JSON.parse(JSON.stringify(health)) }));
  });

  test('the totals line counts only brokers that are in the list', () => {
    assert.match(text, /1 ok, 1 drifted, 1 blocked, 0 dead, 0 error/);
  });

  test('the prose explains the labels and their limits', () => {
    for (const label of ['ok', 'drifted', 'blocked', 'dead', 'error']) assert.match(text, new RegExp(`\`${label}\``));
    assert.match(text, /shape of the form/);
    assert.match(text, /data centre/);
    assert.match(text, /not `drifted`/);
  });

  test('it no longer claims every broker is untested', () => {
    assert.doesNotMatch(text, /labeled `untested`/);
  });
});

describe('STATUS.md in the repo', () => {
  test('equals what the generator produces from brokers.js and data/broker-health.json', () => {
    let health = null;
    try { health = JSON.parse(fs.readFileSync(path.join(ROOT, 'data', 'broker-health.json'), 'utf8')); } catch (_) { /* none yet */ }
    const expected = renderStatus({ brokers: explicitBrokers(brokers), health });
    const actual = fs.readFileSync(path.join(ROOT, 'STATUS.md'), 'utf8');
    assert.equal(actual, expected, 'STATUS.md is out of date: run `node scripts/generate-status.js`');
  });

  test('every checked broker row carries a date', () => {
    const actual = fs.readFileSync(path.join(ROOT, 'STATUS.md'), 'utf8');
    for (const row of rows(actual)) {
      const [name, , , healthCell, checked] = cells(row);
      if (healthCell === 'not checked yet') assert.equal(checked, '-', name);
      else assert.match(checked, /^\d{4}-\d{2}-\d{2}$/, name);
    }
  });
});
